-- NEXA: part 24 of the update. GENERATED by scripts/build-setup-sql.sh, do not edit.
-- Run the parts in order in the Supabase SQL Editor, one after the other.
begin;
-- Wait for a running market tick, keep scheduled jobs out until commit (avoids deadlocks).
select pg_advisory_xact_lock(7311001);

-- ===== supabase/updates/20261204007800_order_fill_preview.sql =====
-- ===== idempotent copy of migrations/20261204007800_order_fill_preview.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 7800 · The preview is the fill: one plan for quote and execution, capped impact (ADR-189)
-- =============================================================================
-- Bug: "I sold for over 100k and got 50k." The order sheet showed quantity x bid (96.000 EUR), the server filled
-- along the player-impact price path (ADR-126): 1 % per 1.000 EUR for a penny stock, so 96.000 EUR moved the price
-- by 96 % and the average fill was 52 % of the bid (58.877,58 shares at 0,8489 EUR = 49.981 EUR). Nothing capped it.
-- Fix (the owner also wants no size limit: "So viel kaufen und verkaufen, wie man mag"):
-- 1. market_order_plan(): the one fill plan (src/lib/sim/order-fill.ts). The n-th share moves the price by
--    min(a x n, maxTickReturnBps): small orders pay half their move as before (ADR-126), but no order can push the
--    price further than one tick can move it, so a large order fills completely at a fair price (at most 10 % from
--    the quote, 96.000 EUR above: average -9,5 % instead of -48 %). No share of a player stock fills outside the
--    daily band (ADR-170). Amounts are solved along the price path.
-- 2. quote_order(): read-only preview with exactly this plan plus fee and the capital gains tax (FIFO lots, loss pot).
-- 3. place_order(): market orders fill exactly the plan; trading.maxOrderQuantity is only a technical bound now.
--    Limit orders are unchanged.
-- Idempotent: runs unchanged as supabase/updates/20261204007800_order_fill_preview.sql.

-- ---------------------------------------------------------------------------
-- A. The fill plan (mirrors planMarketOrder in src/lib/sim/order-fill.ts)
-- ---------------------------------------------------------------------------
-- n-th share moves the price by min(a x n, maxMove); maxMove = trading.maxTickReturnBps (what one tick can move).
-- Summed move of the first x shares: x <= k = maxMove / a: a x^2 / 2, else maxMove x - maxMove k / 2.
create or replace function public.order_move_integral(p_x double precision, p_a double precision, p_m double precision)
returns double precision
language sql
immutable
set search_path = ''
as $function$
  select case when p_a <= 0 then 0
              when p_x <= p_m / p_a then p_a * p_x * p_x / 2
              else p_m * p_x - p_m * (p_m / p_a) / 2 end;
$function$;

-- average fill price (e4) of p_q (e6) shares along that path, inside the band, at least the minimum price
create or replace function public.market_order_avg_e4(
  p_touch bigint, p_dir integer, p_a double precision, p_pos double precision, p_m double precision,
  p_q bigint, p_lo bigint, p_hi bigint, p_min bigint)
returns bigint
language sql
immutable
set search_path = ''
as $function$
  -- the band only stops a move away from the quote: a sale never fills above the bid, a buy never below the ask
  select greatest(p_min, case when p_dir < 0 then least(p_touch, greatest(coalesce(p_lo, x.p), x.p))
                              else greatest(p_touch, least(coalesce(p_hi, x.p), x.p)) end)
    from (select case when p_q <= 0 then p_touch
                      else round(p_touch * (1 + p_dir
                             * (public.order_move_integral(p_pos + p_q / 1000000.0, p_a, p_m)
                                - public.order_move_integral(p_pos, p_a, p_m)) / (p_q / 1000000.0)))::bigint
                 end as p) x;
$function$;

create or replace function public.market_order_plan(
  p_security_id  uuid,
  p_side         public.order_side,
  p_quantity_e6  bigint,
  p_amount_cents bigint
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_trading   jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  s           public.securities;
  v_bid       bigint;
  v_ask       bigint;
  v_prev      bigint;
  v_last      bigint;
  v_pending   bigint;
  v_touch     bigint;
  v_dir       integer;
  v_a         double precision;
  v_pos       double precision;
  v_fee       bigint;
  v_min_price bigint;
  v_m         double precision;
  v_band      double precision;
  v_lo        bigint;
  v_hi        bigint;
  v_q         bigint;
  v_avg       bigint;
  v_lastp     bigint;
  v_gross     bigint := 0;
  v_target    bigint;
  b_lo        bigint;
  b_hi        bigint;
  b_mid       bigint;
  i           integer := 0;
begin
  select * into s from public.securities where id = p_security_id;
  select q.bid_e4, q.ask_e4, q.prev_close_e4, q.last_price_e4 into v_bid, v_ask, v_prev, v_last
    from public.security_quotes q where q.security_id = p_security_id;
  if s.id is null or v_bid is null or v_ask is null then
    return null;
  end if;
  select st.pending_player_flow_e6 into v_pending from public.security_sim_state st where st.security_id = s.id;
  v_pending   := coalesce(v_pending, 0);
  v_fee       := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min_price := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  v_m         := greatest(0, public.cfg_num(v_trading, '{maxTickReturnBps}', 1000)) / 10000.0;
  v_a         := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0
                 / public.security_depth(s.id, public.market_session_at(public.game_now()) = 'regular');
  if p_side = 'buy' then
    v_touch := v_ask;  v_dir := 1;  v_pos := greatest(v_pending, 0) / 1000000.0;
  else
    v_touch := v_bid;  v_dir := -1; v_pos := greatest(-v_pending, 0) / 1000000.0;
  end if;
  if s.kind = 'stock' then
    -- ADR-126: 1 % per depthCentsPer100Bps of value
    v_a := greatest(v_a, 0.01 * (v_touch / 100.0)
                         / greatest(1, public.cfg_num(v_trading,
                                         array['playerImpact', 'depthCentsPer100Bps',
                                               coalesce((select c.tier::text from public.companies c where c.id = s.company_id), 'midcap')],
                                         2500000)));
  end if;
  -- ADR-170: no share of a player stock fills outside the daily band
  v_band := greatest(0, public.cfg_num(v_trading, '{playerStocks,dailyBandBps}', 0)) / 10000.0;
  if s.kind = 'stock' and v_band > 0
     and exists (select 1 from public.player_companies pc where pc.company_id = s.company_id) then
    v_hi := ceil(coalesce(v_prev, v_last, v_touch) * (1 + v_band))::bigint;
    v_lo := floor(coalesce(v_prev, v_last, v_touch) / (1 + v_band))::bigint;
  end if;

  -- quantity: given, or the largest (buy) / smallest (sell) one whose gross matches the amount (bisection)
  if p_quantity_e6 is not null then
    v_q := p_quantity_e6;
  else
    v_target := case when p_side = 'buy' then p_amount_cents - v_fee else p_amount_cents end;
    b_lo := 0;
    b_hi := ceil(v_target * 100000000.0
                 / greatest(1, least(case when p_side = 'buy' then v_touch else v_touch * (1 - v_m) end,
                                     coalesce(v_lo, v_touch))))::bigint + 1;
    if v_target <= 0 then
      b_hi := 0;
    end if;
    while b_hi - b_lo > 1 and i < 200 loop
      b_mid := (b_lo + b_hi) / 2;
      if public.value_cents(b_mid, public.market_order_avg_e4(v_touch, v_dir, v_a, v_pos, v_m, b_mid, v_lo, v_hi, v_min_price))
         <= v_target then
        b_lo := b_mid;
      else
        b_hi := b_mid;
      end if;
      i := i + 1;
    end loop;
    v_q := case when p_side = 'buy' or b_lo = 0 then b_lo
                when public.value_cents(b_lo, public.market_order_avg_e4(v_touch, v_dir, v_a, v_pos, v_m, b_lo, v_lo, v_hi, v_min_price)) >= v_target then b_lo
                else b_hi end;
  end if;

  v_avg := public.market_order_avg_e4(v_touch, v_dir, v_a, v_pos, v_m, v_q, v_lo, v_hi, v_min_price);
  if v_q > 0 then
    v_gross := public.value_cents(v_q, v_avg);
  end if;
  v_lastp := round(v_touch * (1 + v_dir * least(v_a * (v_pos + v_q / 1000000.0), v_m)))::bigint;
  v_lastp := greatest(v_min_price, case when v_dir < 0 then least(v_touch, greatest(coalesce(v_lo, v_lastp), v_lastp))
                                       else greatest(v_touch, least(coalesce(v_hi, v_lastp), v_lastp)) end);

  return jsonb_build_object(
    'touch_e4',              v_touch,
    'requested_quantity_e6', v_q,
    'fill_quantity_e6',      v_q,
    'unfilled_quantity_e6',  0,
    'avg_price_e4',          v_avg,
    'last_price_e4',         v_lastp,
    'gross_cents',           v_gross,
    'fee_cents',             case when v_q > 0 then v_fee else 0 end,
    'slippage_bps',          round(abs(v_avg - v_touch)::double precision / v_touch * 10000)::integer,
    'impact_bps',            round((v_lastp - v_touch)::double precision / v_touch * 10000)::integer,
    'limited_by',            null);
end;
$function$;

revoke all on function public.market_order_plan(uuid, public.order_side, bigint, bigint) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- B. quote_order: the preview the order sheet shows before confirming
-- ---------------------------------------------------------------------------
create or replace function public.quote_order(
  p_ticker       text,
  p_side         text,
  p_quantity_e6  bigint default null,
  p_amount_cents bigint default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  v_player  uuid := public.require_player();
  v_trading jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  s         public.securities;
  v_side    public.order_side;
  v_plan    jsonb;
  v_pos     public.positions;
  v_fill    bigint;
  v_left    bigint;
  v_take    bigint;
  v_cost    bigint := 0;
  v_pnl     bigint;
  v_pot     bigint;
  v_tax     bigint := 0;
  v_gross   bigint;
  v_fee     bigint;
  lot       record;
begin
  if lower(coalesce(p_side, '')) not in ('buy', 'sell') or (p_quantity_e6 is null) = (p_amount_cents is null)
     or coalesce(p_quantity_e6, p_amount_cents) < 1 then
    perform public.api_error('invalid_argument');
  end if;
  v_side := lower(p_side)::public.order_side;
  select * into s from public.securities where id = public.resolve_security(p_ticker);
  if s.id is null then
    perform public.api_error('unknown_security');
  end if;
  v_plan := public.market_order_plan(s.id, v_side, p_quantity_e6, p_amount_cents);
  if v_plan is null then
    perform public.api_error('not_tradable');
  end if;
  -- ADR-153: a buy gets at most the free shares, as place_order does
  if v_side = 'buy' and s.kind = 'stock' and public.security_free_float_e6(s.id) is not null
     and (v_plan ->> 'fill_quantity_e6')::bigint > greatest(0, public.security_free_float_e6(s.id)) then
    v_fill := (v_plan ->> 'requested_quantity_e6')::bigint;
    v_plan := public.market_order_plan(s.id, v_side, greatest(0, public.security_free_float_e6(s.id)), null)
              || jsonb_build_object('requested_quantity_e6', v_fill,
                                    'unfilled_quantity_e6', v_fill - greatest(0, public.security_free_float_e6(s.id)),
                                    'limited_by', 'supply');
  end if;
  v_fill  := (v_plan ->> 'fill_quantity_e6')::bigint;
  v_fee   := (v_plan ->> 'fee_cents')::bigint;
  v_gross := (v_plan ->> 'gross_cents')::bigint;
  v_fee   := (v_plan ->> 'fee_cents')::bigint;

  -- sells: capital gains tax exactly like execute_fill (FIFO lots, loss pot)
  if v_side = 'sell' and v_fill > 0 then
    select * into v_pos from public.positions p
     where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open';
    if v_pos.id is not null then
      v_left := v_fill;
      for lot in
        select l.quantity_open_e6, l.price_e4 from public.position_lots l
         where l.position_id = v_pos.id and l.quantity_open_e6 > 0 order by l.acquired_at, l.id
      loop
        exit when v_left = 0;
        v_take := least(v_left, lot.quantity_open_e6);
        v_cost := v_cost + public.value_cents(v_take, lot.price_e4);
        v_left := v_left - v_take;
      end loop;
      if v_left > 0 then
        v_cost := v_cost + public.value_cents(v_left, v_pos.avg_entry_price_e4);
      end if;
      v_pnl := v_gross - v_fee - v_cost;
      select pp.tax_loss_pot_cents into v_pot from public.player_private pp where pp.player_id = v_player;
      if v_pnl > 0 then
        v_tax := public.apply_bps(v_pnl - least(v_pnl, coalesce(v_pot, 0)),
                                  public.cfg_num(v_trading, '{capitalGainsTaxBps}', 2500)::numeric);
      end if;
    end if;
  end if;

  return v_plan || jsonb_build_object(
    'ticker',             s.ticker,
    'side',               v_side,
    'tax_cents',          v_tax,
    'realized_pnl_cents', v_pnl,
    -- what the player pays (buy) or receives (sell) in cash
    'net_cents',          case when v_fill = 0 then 0
                               when v_side = 'buy' then v_gross + v_fee
                               else v_gross - v_fee - v_tax end);
end;
$function$;

revoke all on function public.quote_order(text, text, bigint, bigint) from public, anon;
grant execute on function public.quote_order(text, text, bigint, bigint) to authenticated;

-- ---------------------------------------------------------------------------
-- C. place_order: market orders fill exactly the plan (full latest definition, incl. ADR-153 and ADR-170)
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_request_id     uuid,
  p_ticker         text,
  p_side           text,
  p_type           text,
  p_quantity_e6    bigint default null,
  p_limit_price_e4 bigint default null,
  p_amount_cents   bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_player     uuid;
  v_replay     jsonb;
  v_trading    jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_abuse      jsonb := coalesce(public.config_jsonb('abuse'), '{}'::jsonb);
  v_scale      numeric := greatest(1, public.cfg_num(v_trading, '{quantityScale}', 1000000))::numeric;
  v_side       public.order_side;
  v_type       public.order_type;
  v_limit      bigint;
  s            public.securities;
  v_level      integer;
  v_cash       bigint;
  v_bid        bigint;
  v_ask        bigint;
  v_pending    bigint;
  v_regular    boolean;
  v_depth      double precision;
  v_a          double precision;
  v_pos        double precision;
  v_touch      bigint;
  v_qty        bigint;
  v_fill_qty   bigint := 0;
  v_fill_price bigint;
  v_rest       bigint;
  v_fee        bigint;
  v_min_value  bigint;
  v_need       bigint;
  v_reserve    bigint := 0;
  v_avail      bigint;
  v_net_amount bigint;
  v_order_id   uuid := gen_random_uuid();
  v_fill       jsonb;
  o            public.orders;
  v_prof       public.profiles;
  v_min_price  bigint;
  v_plan       jsonb;
  v_requested  bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'place_order');
  if v_replay is not null then
    return v_replay;
  end if;

  -- inputs -------------------------------------------------------------------
  if lower(coalesce(p_side, '')) not in ('buy', 'sell') or lower(coalesce(p_type, '')) not in ('market', 'limit')
     or (p_quantity_e6 is null) = (p_amount_cents is null) then
    perform public.api_error('invalid_argument');
  end if;
  v_side := lower(p_side)::public.order_side;
  v_type := lower(p_type)::public.order_type;
  if (p_quantity_e6 is not null and p_quantity_e6 < 1) or (p_amount_cents is not null and p_amount_cents < 1) then
    perform public.api_error('invalid_quantity');
  end if;
  if v_type = 'limit' then
    if p_limit_price_e4 is null or p_limit_price_e4 < 1 or p_limit_price_e4 > 100000000000 then
      perform public.api_error('invalid_price');
    end if;
    v_limit := p_limit_price_e4;
  end if;

  select * into s from public.securities where id = public.resolve_security(p_ticker);
  if s.id is null then
    perform public.api_error('unknown_security');
  end if;
  if s.kind not in ('stock', 'bond') or s.status <> 'listed' or not s.is_tradable then
    perform public.api_error('not_tradable');
  end if;
  if (select r.is_paused from public.sim_runtime r where r.id) then
    perform public.api_error('market_paused');
  end if;

  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_type = 'limit' and v_level < public.unlock_level('limit_orders') then
    perform public.api_error('locked');
  end if;
  if s.kind = 'bond' and v_level < public.unlock_level('bonds') then
    perform public.api_error('locked');
  end if;
  -- ADR-170: no buying the own stock with money just taken out of the company
  if v_side = 'buy' and s.kind = 'stock' and public.player_stock_insider_blocked(v_player, s.id) then
    perform public.api_error('insider_cooldown');
  end if;

  if not public.rate_limit_hit(v_player, 'place_order',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerMinute}', 20))::integer, 60)
     or not public.rate_limit_hit(v_player, 'place_order_day',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerDay}', 500))::integer, 86400) then
    perform public.api_error('rate_limited');
  end if;

  -- locks, quote ---------------------------------------------------------------
  v_cash := public.lock_player_accounts(v_player);
  select q.bid_e4, q.ask_e4 into v_bid, v_ask from public.security_quotes q where q.security_id = s.id;
  select st.pending_player_flow_e6 into v_pending from public.security_sim_state st where st.security_id = s.id;
  if v_bid is null or v_ask is null then
    perform public.api_error('not_tradable');
  end if;
  v_pending   := coalesce(v_pending, 0);
  v_regular   := public.market_session_at(public.game_now()) = 'regular';
  v_depth     := public.security_depth(s.id, v_regular);                 -- whole shares
  v_a         := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0 / v_depth;
  v_fee       := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min_value := greatest(1, public.cfg_num(v_trading, '{minOrderValueCents}', 100))::bigint;
  v_min_price := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  if v_side = 'buy' then
    v_touch := v_ask;
    v_pos := greatest(v_pending, 0) / 1000000.0;
  else
    v_touch := v_bid;
    v_pos := greatest(-v_pending, 0) / 1000000.0;
  end if;
  -- Stocks: a fill pays for the move it causes (ADR-126). The next tick moves the price by the player impact
  -- (0.01 x value / depthCentsPer100Bps); the fill pays half of that on average, so buying and selling right away
  -- can never earn the move one causes oneself.
  if s.kind = 'stock' then
    v_a := greatest(v_a, 0.01 * (v_touch / 100.0)
                         / greatest(1, public.cfg_num(v_trading,
                                         array['playerImpact', 'depthCentsPer100Bps',
                                               coalesce((select c.tier::text from public.companies c where c.id = s.company_id), 'midcap')],
                                         2500000)));
  end if;

  -- quantity from the amount (neo-broker semantics) ------------------------------
  if p_amount_cents is not null then
    if v_side = 'buy' then
      -- the player pays at most the amount including the fee
      v_net_amount := p_amount_cents - v_fee;
      if v_net_amount < v_min_value then
        perform public.api_error('order_too_small');
      end if;
      if v_type = 'limit' then
        v_qty := floor(v_net_amount * 100000000.0 / v_limit)::bigint;
      else
        -- ADR-189: the quantity the amount buys along the price path, the same plan the preview shows
        v_qty := (public.market_order_plan(s.id, v_side, null, p_amount_cents) ->> 'requested_quantity_e6')::bigint;
      end if;
    else
      -- the amount is the gross proceeds before fee and tax
      if p_amount_cents < v_min_value then
        perform public.api_error('order_too_small');
      end if;
      if v_type = 'limit' then
        v_qty := ceil(p_amount_cents * 100000000.0 / v_limit)::bigint;
      else
        v_qty := (public.market_order_plan(s.id, v_side, null, p_amount_cents) ->> 'requested_quantity_e6')::bigint;
      end if;
    end if;
  else
    v_qty := p_quantity_e6;
  end if;
  v_requested := v_qty;

  if v_qty < 1 then
    perform public.api_error('order_too_small');
  end if;
  if v_qty > public.cfg_num(v_trading, '{maxOrderQuantity}', 100000) * v_scale then
    perform public.api_error('invalid_quantity');
  end if;

  -- sells: free position; >= 99.9 % of it is rounded up to the whole position
  if v_side = 'sell' then
    select p.quantity_e6 - p.reserved_quantity_e6 into v_avail
      from public.positions p
     where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open'
       for update;
    v_avail := coalesce(v_avail, 0);
    if v_qty < v_avail and v_qty * 1000 >= v_avail * 999 then
      v_qty := v_avail;
    end if;
    if v_avail < v_qty then
      perform public.api_error('insufficient_position');
    end if;
  end if;

  -- ADR-153: a stock has a supply. Buyers of one stock go one after the other, so the float cannot be oversold.
  if v_side = 'buy' and s.kind = 'stock' then
    perform 1 from public.securities x where x.id = s.id for update;
    if public.security_free_float_e6(s.id) is not null then
      if public.security_free_float_e6(s.id) < 1 then
        perform public.api_error('no_shares_left');
      end if;
      v_qty := least(v_qty, public.security_free_float_e6(s.id));
    end if;
  end if;

  -- minimum order value at the price it would execute or rest at
  if public.value_cents(v_qty, coalesce(v_limit, v_touch)) < v_min_value
     and not (v_side = 'sell' and v_qty = v_avail) then
    perform public.api_error('order_too_small');
  end if;

  -- how much executes now ---------------------------------------------------------
  if v_type = 'market' then
    -- ADR-189: the fill is exactly the plan the preview (quote_order) showed, for any quantity
    v_plan := public.market_order_plan(s.id, v_side, v_qty, null);
    v_fill_qty := v_qty;
    v_fill_price := (v_plan ->> 'avg_price_e4')::bigint;
  elsif v_side = 'buy' and v_touch <= v_limit then
    if v_touch * (1 + v_a * (v_pos + v_qty / v_scale)) <= v_limit then
      v_fill_qty := v_qty;
    else
      v_fill_qty := greatest(0, least(v_qty, floor(((v_limit::double precision / v_touch - 1) / v_a - v_pos) * v_scale)::bigint));
    end if;
  elsif v_side = 'sell' and v_touch >= v_limit then
    if v_touch * (1 - v_a * (v_pos + v_qty / v_scale)) >= v_limit then
      v_fill_qty := v_qty;
    else
      v_fill_qty := greatest(0, least(v_qty, floor(((1 - v_limit::double precision / v_touch) / v_a - v_pos) * v_scale)::bigint));
    end if;
  end if;

  if v_fill_qty > 0 then
    if v_side = 'buy' then
      if v_type = 'limit' then
        v_fill_price := round(v_touch * (1 + v_a * (v_pos + v_fill_qty / v_scale / 2)))::bigint;
      end if;
      if v_type = 'limit' then
        v_fill_price := least(v_fill_price, v_limit);
      end if;
    else
      if v_type = 'limit' then
        v_fill_price := greatest(v_min_price, round(v_touch * (1 - v_a * (v_pos + v_fill_qty / v_scale / 2)))::bigint);
      end if;
      if v_type = 'limit' then
        v_fill_price := greatest(v_fill_price, v_limit);
      end if;
    end if;
  end if;
  v_rest := v_qty - v_fill_qty;

  if v_side = 'buy' then
    v_need := 0;
    if v_fill_qty > 0 then
      v_need := public.value_cents(v_fill_qty, v_fill_price) + v_fee;
    end if;
    if v_rest > 0 then
      v_need := v_need + public.value_cents(v_rest, v_limit) + case when v_fill_qty > 0 then 0 else v_fee end;
    end if;
    if v_need > v_cash then
      perform public.api_error('insufficient_funds');
    end if;
  end if;

  -- order, fill, reservation ---------------------------------------------------------
  insert into public.orders (id, player_id, security_id, request_id, side, type, quantity_e6, limit_price_e4, status)
  values (v_order_id, v_player, s.id, p_request_id, v_side, v_type, v_qty, v_limit, 'pending');

  if v_fill_qty > 0 then
    v_fill := public.execute_fill(v_order_id, v_fill_qty, v_fill_price, false, false);
  end if;

  if v_rest > 0 then
    select * into o from public.orders where id = v_order_id;
    if v_side = 'buy' then
      v_reserve := public.value_cents(v_rest, v_limit) + case when o.fee_cents = 0 then v_fee else 0 end;
      if v_reserve > 0 then
        perform public.ledger_transfer(
          public.ledger_player_account(v_player, 'player_cash'),
          public.ledger_player_account(v_player, 'player_reserve'),
          v_reserve, 'order_reserve', 'Reservierung Limit-Order', 'order', v_order_id,
          'reserve:' || v_order_id::text, v_player);
      end if;
      update public.orders set reserved_cents = v_reserve where id = v_order_id;
    else
      update public.positions p
         set reserved_quantity_e6 = p.reserved_quantity_e6 + v_rest
       where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open';
      update public.orders set reserved_quantity_e6 = v_rest where id = v_order_id;
    end if;
    update public.orders
       set status = case when v_fill_qty > 0 then 'partially_filled'::public.order_status else 'open'::public.order_status end
     where id = v_order_id;
  end if;
  if v_type = 'limit' then
    perform public.mission_event(v_player, 'limit_order', 1, null);
  end if;

  select * into o from public.orders where id = v_order_id;
  select * into v_prof from public.profiles where id = v_player;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'order_id',           o.id,
    'status',             o.status,
    'quantity_e6',        o.quantity_e6,
    'filled_quantity_e6', o.filled_quantity_e6,
    'avg_price_e4',       o.avg_fill_price_e4,
    'gross_cents',        coalesce((v_fill ->> 'gross_cents')::bigint, 0),
    'fee_cents',          o.fee_cents,
    'tax_cents',          coalesce((v_fill ->> 'tax_cents')::bigint, 0),
    'realized_pnl_cents', (v_fill ->> 'realized_pnl_cents')::bigint,
    'cash_cents',         (select a.balance_cents from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash'),
    'reserved_cents',     o.reserved_cents,
    'xp_awarded',         coalesce((v_fill ->> 'xp_awarded')::integer, 0),
    'level',              v_prof.level,
    'xp_total',           v_prof.xp_total,
    'ticker',             s.ticker,
    'side',               o.side,
    'type',               o.type,
    'limit_price_e4',     o.limit_price_e4,
    'amount_cents',       p_amount_cents,
    'requested_quantity_e6', coalesce(v_requested, o.quantity_e6),
    'unfilled_quantity_e6',  case when v_type = 'market' then greatest(0, v_requested - o.quantity_e6) else 0 end,
    -- only the stock supply (ADR-153) can make a market order smaller than asked
    'limited_by',            case when v_type = 'market' and v_requested > o.quantity_e6 then 'supply' end,
    'impact_bps',            coalesce((v_plan ->> 'impact_bps')::integer, 0)));
end;
$function$;

revoke all on function public.place_order(uuid, text, text, text, bigint, bigint, bigint) from public, anon;
grant execute on function public.place_order(uuid, text, text, text, bigint, bigint, bigint) to authenticated;

-- ===== supabase/updates/20261204007900_nexamon_big_pull_notify.sql =====
-- ===== idempotent copy of migrations/20261204007900_nexamon_big_pull_notify.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 7900 · Nexamon: a big pull is news for everyone (ADR-190)
-- =============================================================================
-- * Trigger nexamon_big_pull_notify on nexamon_copies (AFTER INSERT): a copy a player pulls from a pack (source
--   'pack' with a pack id: bought, multi-buy, sealed, Pack Battle; never the AI) worth more than
--   nexamon.bigPullNotifyCents at pull time (copy value incl. condition) tells every other active player
--   (notification nexamon_big_pull, link to the card page) and posts the feed item nexamon_big_pull.
-- * One of Ones are skipped (they already notify everyone), so are sets not released at pull time; rarities in
--   feedRarities get no second feed item (nexamon_pull covers them).
-- * At most one broadcast per puller every nexamon.bigPullNotifySeconds (nexamon_big_pull_broadcasts). Several
--   big pulls in one transaction (one opening or multi-buy) update that one notification: count and best card.
-- Idempotent: runs unchanged as supabase/updates/20261204007900_nexamon_big_pull_notify.sql.

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('nexamon_big_pull', 'social', 'Großer Nexamon-Zug', 'Jemand hat eine Nexamon-Karte mit sehr hohem Wert gezogen.',
        'notif_bell', true, false, false, 303)
on conflict (key) do nothing;

create table if not exists public.nexamon_big_pull_broadcasts (
  player_id    uuid primary key references public.profiles (id) on delete cascade,
  tx_id        bigint not null,
  broadcast_at timestamptz not null,
  dedupe_key   text not null,
  cards        jsonb not null default '[]'::jsonb
);
comment on table public.nexamon_big_pull_broadcasts is
  'Last big-pull broadcast per puller (rate limit and combining one opening into one notification; ADR-190).';
alter table public.nexamon_big_pull_broadcasts enable row level security;
revoke all on public.nexamon_big_pull_broadcasts from public, anon, authenticated;
grant all on public.nexamon_big_pull_broadcasts to service_role;

create or replace function public.nexamon_big_pull_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.nexamon_cfg();
  k        public.nexamon_cards;
  b        public.nexamon_big_pull_broadcasts;
  v_min    bigint := coalesce((cfg ->> 'bigPullNotifyCents')::bigint, 10000000);
  v_secs   integer := coalesce((cfg ->> 'bigPullNotifySeconds')::integer, 60);
  v_value  bigint;
  v_tx     bigint := txid_current();
  v_same   boolean;
  v_name   text;
  v_nick   text;
  v_cards  jsonb;
  v_best   jsonb;
  v_n      integer;
  v_body   text;
  v_key    text;
  r        record;
begin
  if new.owner_id is null or new.ai_owner is not null or new.source <> 'pack' or new.pack_id is null then
    return null;
  end if;
  select * into k from public.nexamon_cards c where c.card_key = new.card_key;
  if k.card_key is null or k.rarity = 'one_of_one' or not public.nexamon_set_released(k.set_key, new.created_at) then
    return null;
  end if;
  v_value := public.nexamon_copy_value_cents(k.value_e4, new.condition, null);
  if v_value <= v_min then
    return null;
  end if;
  v_name := coalesce((select g.value ->> k.card_key from public.game_config g where g.key = 'nexamon_names'), k.card_key);
  select p.nickname into v_nick from public.profiles p where p.id = new.owner_id;
  if not coalesce(cfg -> 'feedRarities', '[]'::jsonb) ? k.rarity then
    perform public.feed_post(new.owner_id, 'nexamon_big_pull',
                             jsonb_build_object('card_key', k.card_key, 'set', k.set_key, 'rarity', k.rarity, 'name', v_name,
                                                'serial', new.serial, 'condition', new.condition, 'value_cents', v_value),
                             'nexamon:bigpull:' || new.id::text);
  end if;

  select * into b from public.nexamon_big_pull_broadcasts x where x.player_id = new.owner_id for update;
  v_same := b.player_id is not null and b.tx_id = v_tx;
  v_cards := jsonb_build_array(jsonb_build_object('card_key', k.card_key, 'name', v_name, 'value_cents', v_value));
  if v_same then
    v_cards := b.cards || v_cards;
  elsif b.player_id is not null and new.created_at < b.broadcast_at + make_interval(secs => v_secs) then
    return null;
  end if;
  select c into v_best from jsonb_array_elements(v_cards) c order by (c ->> 'value_cents')::bigint desc limit 1;
  v_n := jsonb_array_length(v_cards);
  v_body := coalesce(v_nick, '?') || ' hat '
            || case when v_n = 1 then (v_best ->> 'name')
                    else v_n || ' Karten über ' || public.format_eur(v_min) || ' gezogen, darunter ' || (v_best ->> 'name') end
            || case when v_n = 1 then ' gezogen' else '' end
            || ' – Wert ' || public.format_eur((v_best ->> 'value_cents')::bigint) || '!';

  if v_same then
    update public.nexamon_big_pull_broadcasts set cards = v_cards where player_id = new.owner_id;
    update public.notifications n
       set body = left(v_body, 500), link = '/nexamon/' || (v_best ->> 'card_key'),
           payload = jsonb_build_object('card_key', v_best ->> 'card_key', 'nickname', v_nick,
                                        'value_cents', (v_best ->> 'value_cents')::bigint, 'count', v_n)
     where n.type_key = 'nexamon_big_pull' and n.dedupe_key = b.dedupe_key;
    return null;
  end if;

  v_key := 'nexamon:bigpull:' || new.owner_id::text || ':' || v_tx::text;
  insert into public.nexamon_big_pull_broadcasts (player_id, tx_id, broadcast_at, dedupe_key, cards)
  values (new.owner_id, v_tx, new.created_at, v_key, v_cards)
  on conflict (player_id) do update
    set tx_id = excluded.tx_id, broadcast_at = excluded.broadcast_at, dedupe_key = excluded.dedupe_key,
        cards = excluded.cards;
  for r in select p.id from public.profiles p where not p.is_deactivated and p.id <> new.owner_id loop
    perform public.social_notify(r.id, 'nexamon_big_pull', 'Großer Zug!', v_body,
      jsonb_build_object('card_key', k.card_key, 'nickname', v_nick, 'value_cents', v_value, 'count', 1),
      '/nexamon/' || k.card_key, v_key);
  end loop;
  return null;
end;
$$;
comment on function public.nexamon_big_pull_notify() is
  'Trigger: a player''s pack pull above nexamon.bigPullNotifyCents notifies every other active player (ADR-190).';
revoke all on function public.nexamon_big_pull_notify() from public, anon, authenticated;

drop trigger if exists nexamon_big_pull_notify on public.nexamon_copies;
create trigger nexamon_big_pull_notify
  after insert on public.nexamon_copies
  for each row execute function public.nexamon_big_pull_notify();

-- ===== supabase/updates/20261204008100_news_promos.sql =====
-- ===== idempotent copy of migrations/20261204008100_news_promos.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 8100 · News-Aktionen: the live show announces a promotion (ADR-193)
-- =============================================================================
-- * news_promos: one row per promotion (kind pack_sale | free_nft | tax_return), tied to the show that announced
--   it, running from the show start for newsPromos.durationMinutes. At most one runs at a time.
-- * news_promo_claims: who used a promotion (free NFT, tax return); one row per player and promotion.
-- * Trigger news_shows_promo (BEFORE UPDATE when a show goes on air): with chance newsPromos.chanceBps the show
--   brings a promotion of a kind other than the previous one; Mr. Doodle Dangle reads it as the last segment
--   (kind 'promo'), the news feed keeps it and every player active in the last notifyActiveDays days gets the
--   notification news_promo (once per player and promotion).
-- * pack_sale: buy_nexamon_pack and buy_nexamon_sealed_pack (latest definitions, 5210/6710 patched by 7240) take
--   their price from news_promo_pack_price: −discountBps for packs of the drawn released set while it runs.
--   buy_nexamon_packs (multi-buy) calls buy_nexamon_pack. Pack battles keep their price.
-- * free_nft: create_artwork (latest definition, 6110 era) mints the first NFT of a player within the promotion
--   without the fee and records the claim.
-- * tax_return: RPC file_news_tax_return pays newsPromos.taxReturn.shareBps of the sales revenue of the player's
--   active companies in the last windowHours closed hours, at most capCents, from the state treasury
--   (ledger kind tax_refund, sum 0, idempotent by request id). AI companies have no founder and never qualify.
-- * RPC get_news_promo: the running promotion with its end, the own claim and the own tax amount.
-- Idempotent: runs unchanged as supabase/updates/20261204008100_news_promos.sql.

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, sort_order)
values ('news_promo', 'social', 'News-Aktion', 'Mr. Doodle Dangle hat in der Show eine Aktion für alle angekündigt.',
        'notif_bell', true, false, 300)
on conflict (key) do nothing;

create table if not exists public.news_promos (
  id         bigint generated always as identity primary key,
  kind       text not null check (kind in ('pack_sale', 'free_nft', 'tax_return')),
  show_id    bigint unique references public.news_shows (id) on delete set null,
  set_key    text,
  bps        integer not null default 0,
  starts_at  timestamptz not null,
  ends_at    timestamptz not null,
  headline   text not null,
  body       text not null,
  created_at timestamptz not null default now(),
  check (ends_at > starts_at),
  check ((kind = 'pack_sale') = (set_key is not null))
);
create index if not exists news_promos_ends_idx on public.news_promos (ends_at desc);
alter table public.news_promos enable row level security;
drop policy if exists news_promos_read on public.news_promos;
create policy news_promos_read on public.news_promos for select to authenticated using (true);
comment on table public.news_promos is
  'News-Aktionen (ADR-193): a promotion announced in the live show, from starts_at to ends_at; at most one at a time.';

create table if not exists public.news_promo_claims (
  promo_id     bigint not null references public.news_promos (id) on delete cascade,
  player_id    uuid not null references public.profiles (id) on delete cascade,
  amount_cents bigint not null default 0 check (amount_cents >= 0),
  revenue_cents bigint,
  ref_id       uuid,
  created_at   timestamptz not null default now(),
  primary key (promo_id, player_id)
);
create index if not exists news_promo_claims_player_idx on public.news_promo_claims (player_id);
alter table public.news_promo_claims enable row level security;
drop policy if exists news_promo_claims_own on public.news_promo_claims;
create policy news_promo_claims_own on public.news_promo_claims for select to authenticated
  using (player_id = (select auth.uid()));
comment on table public.news_promo_claims is
  'News-Aktionen (ADR-193): a free NFT (amount = fee saved, ref = artwork) or a tax return (amount = refund) per player.';

create or replace function public.news_promos_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select value from public.game_config where key = 'newsPromos'), '{}'::jsonb);
$$;

-- The promotion running at p_now (at most one).
create or replace function public.news_promo_active(p_now timestamptz)
returns public.news_promos
language sql
stable
security definer
set search_path = ''
as $$
  select p.* from public.news_promos p
   where p.starts_at <= p_now and p.ends_at > p_now
   order by p.starts_at desc
   limit 1;
$$;

-- Price of a pack of p_set at p_now: the configured price, less the pack sale of that set while it runs.
create or replace function public.news_promo_pack_price(p_set text, p_price bigint, p_now timestamptz)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v public.news_promos;
begin
  if p_price is null or p_price <= 0 then
    return p_price;
  end if;
  v := public.news_promo_active(p_now);
  if v.id is not null and v.kind = 'pack_sale' and v.set_key = p_set then
    return public.apply_bps(p_price, 10000 - v.bps);
  end if;
  return p_price;
end;
$$;

-- Sales revenue of the player's active companies in the last windowHours closed hours, and the refund.
create or replace function public.news_promo_tax(p_player uuid, p_now timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.news_promos_cfg() -> 'taxReturn';
  v_to      timestamptz := date_trunc('hour', p_now);
  v_from    timestamptz := date_trunc('hour', p_now) - make_interval(hours => coalesce((cfg ->> 'windowHours')::integer, 24));
  v_cap     bigint := coalesce((cfg ->> 'capCents')::bigint, 5000000);
  v_owner   boolean;
  v_revenue bigint;
  v_refund  bigint;
begin
  v_owner := exists (select 1 from public.player_companies pc where pc.founder_id = p_player and pc.status = 'active');
  select coalesce(sum(h.revenue_cents), 0)::bigint into v_revenue
    from public.player_company_hours h
    join public.player_companies pc on pc.company_id = h.company_id
   where pc.founder_id = p_player and pc.status = 'active'
     and h.hour_start >= v_from and h.hour_start < v_to;
  v_refund := case when v_revenue <= 0 then 0
                   else least(v_cap, public.apply_bps(v_revenue, coalesce((cfg ->> 'shareBps')::integer, 1000))) end;
  return jsonb_build_object('owner', v_owner, 'revenue_cents', v_revenue, 'refund_cents', v_refund, 'cap_cents', v_cap,
                            'share_bps', coalesce((cfg ->> 'shareBps')::integer, 1000));
end;
$$;

-- The draw (ADR-193): with p_roll < chanceBps a promotion of a kind other than the previous one. Rolls in [0, 1).
-- Returns the show segment for Mr. Doodle Dangle, or null.
create or replace function public.news_promo_draw(p_show_id bigint, p_now timestamptz,
                                                  p_roll double precision default random(),
                                                  p_pick double precision default random())
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg     jsonb := public.news_promos_cfg();
  v_last  text;
  v_kinds text[];
  v_kind  text;
  v_set   text;
  v_bps   integer := 0;
  v_mins  integer := coalesce((cfg ->> 'durationMinutes')::integer, 15);
  v_line  jsonb;
  v_head  text;
  v_body  text;
  v_cap   bigint := coalesce((cfg #>> '{taxReturn,capCents}')::bigint, 5000000);
  v_name  text;
  v_id    bigint;
  r       record;
begin
  if p_roll * 10000 >= coalesce((cfg ->> 'chanceBps')::integer, 0)
     or (p_show_id is not null and exists (select 1 from public.news_promos p where p.show_id = p_show_id))
     or (public.news_promo_active(p_now)).id is not null then
    return null;
  end if;
  select p.kind into v_last from public.news_promos p order by p.starts_at desc, p.id desc limit 1;
  select coalesce(array_agg(k order by o), '{}') into v_kinds
    from jsonb_array_elements_text(coalesce(cfg -> 'kinds', '["pack_sale","free_nft","tax_return"]'::jsonb))
         with ordinality as x(k, o)
   where k is distinct from v_last;
  -- a pack sale needs a released set with a price; without one it is left out
  select s.key into v_set
    from jsonb_each(public.nexamon_cfg() -> 'sets') s
   where coalesce((s.value ->> 'packPriceCents')::bigint, 0) > 0
     and public.nexamon_set_released(s.key, p_now)
     and exists (select 1 from public.nexamon_cards k where k.set_key = s.key and k.in_catalogue)
   order by md5(s.key || p_pick::text)
   limit 1;
  if v_set is null then
    v_kinds := array_remove(v_kinds, 'pack_sale');
  end if;
  if cardinality(v_kinds) = 0 then
    return null;
  end if;
  v_kind := v_kinds[1 + least(cardinality(v_kinds) - 1, floor(p_pick * cardinality(v_kinds))::integer)];
  if v_kind <> 'pack_sale' then
    v_set := null;
  end if;
  v_bps := case v_kind when 'pack_sale' then coalesce((cfg #>> '{packSale,discountBps}')::integer, 2000)
                       when 'tax_return' then coalesce((cfg #>> '{taxReturn,shareBps}')::integer, 1000)
                       else 0 end;
  select x into v_line from jsonb_array_elements(cfg -> 'lines' -> v_kind) x order by random() limit 1;
  v_name := regexp_replace(coalesce(public.nexamon_cfg() #>> array['sets', v_set, 'name'], v_set, ''), '^Nexamon: ', '');
  select replace(replace(replace(replace(t, '{set}', v_name), '{pct}', (v_bps / 100)::text), '{minutes}', v_mins::text),
                 '{cap}', replace(to_char(v_cap / 100, 'FM999,999,999,999'), ',', '.') || ' €')
    into v_head from (select coalesce(v_line ->> 'headline', 'News-Aktion') t) q;
  select replace(replace(replace(replace(t, '{set}', v_name), '{pct}', (v_bps / 100)::text), '{minutes}', v_mins::text),
                 '{cap}', replace(to_char(v_cap / 100, 'FM999,999,999,999'), ',', '.') || ' €')
    into v_body from (select coalesce(v_line ->> 'text', '') t) q;
  insert into public.news_promos (kind, show_id, set_key, bps, starts_at, ends_at, headline, body)
  values (v_kind, p_show_id, v_set, v_bps, p_now, p_now + make_interval(mins => v_mins), v_head, v_body)
  returning id into v_id;
  insert into public.news_items (category, headline, body, importance, published_at)
  values ('market', v_head, v_body, 2, p_now + interval '59 seconds');
  for r in select p.id from public.profiles p
            where not p.is_deactivated
              and p.last_active_at >= p_now - make_interval(days => coalesce((cfg ->> 'notifyActiveDays')::integer, 7)) loop
    perform public.social_notify(r.id, 'news_promo', v_head, v_body,
      jsonb_build_object('promo_id', v_id, 'kind', v_kind, 'set', v_set),
      case v_kind when 'pack_sale' then '/nexamon' when 'free_nft' then '/artworks' else '/company' end,
      'news_promo:' || v_id::text);
  end loop;
  return jsonb_build_object('kind', 'promo', 'mood', 'proud', 'headline', v_head, 'text', v_body,
                            'effects', jsonb_build_array(jsonb_build_object('label', v_head, 'tone', 'gain')),
                            'promo', jsonb_build_object('id', v_id, 'kind', v_kind, 'set', v_set));
end;
$$;
revoke all on function public.news_promo_draw(bigint, timestamptz, double precision, double precision) from public, anon, authenticated;
revoke all on function public.news_promo_tax(uuid, timestamptz) from public, anon, authenticated;
revoke all on function public.news_promo_pack_price(text, bigint, timestamptz) from public, anon, authenticated;
revoke all on function public.news_promo_active(timestamptz) from public, anon, authenticated;
revoke all on function public.news_promos_cfg() from public, anon, authenticated;

-- A show going on air (news_show_start sets status 'aired') may bring a promotion as its last segment.
create or replace function public.news_shows_promo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_seg jsonb;
begin
  v_seg := public.news_promo_draw(new.id, coalesce(new.started_at, public.game_now()));
  if v_seg is not null then
    new.segments := coalesce(new.segments, '[]'::jsonb) || jsonb_build_array(v_seg);
  end if;
  return new;
end;
$$;
revoke all on function public.news_shows_promo() from public, anon, authenticated;
drop trigger if exists news_shows_promo on public.news_shows;
create trigger news_shows_promo
  before update of status on public.news_shows
  for each row
  when (old.status = 'scheduled' and new.status = 'aired')
  execute function public.news_shows_promo();

-- ---------------------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------------------
create or replace function public.get_news_promo()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid := (select auth.uid());
  v_now    timestamptz := public.game_now();
  v        public.news_promos;
  c        public.news_promo_claims;
begin
  if v_player is null then
    perform public.api_error('not_authenticated');
  end if;
  v := public.news_promo_active(v_now);
  if v.id is null then
    return jsonb_build_object('now', v_now, 'promo', null);
  end if;
  select * into c from public.news_promo_claims x where x.promo_id = v.id and x.player_id = v_player;
  return jsonb_build_object('now', v_now, 'promo', jsonb_build_object(
    'id', v.id, 'kind', v.kind, 'set', v.set_key, 'bps', v.bps, 'starts_at', v.starts_at, 'ends_at', v.ends_at,
    'headline', v.headline, 'text', v.body,
    'claimed', c.promo_id is not null, 'claimed_cents', c.amount_cents,
    'tax', case when v.kind = 'tax_return' then public.news_promo_tax(v_player, v_now) else null end));
end;
$$;
comment on function public.get_news_promo() is
  'RPC: the running News-Aktion (ADR-193) -> {now, promo: {id, kind, set, bps, starts_at, ends_at, headline, text, '
  'claimed, claimed_cents, tax: {owner, revenue_cents, refund_cents, cap_cents, share_bps} | null} | null}.';
revoke all on function public.get_news_promo() from public, anon;
grant execute on function public.get_news_promo() to authenticated;

create or replace function public.file_news_tax_return(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_now    timestamptz := public.game_now();
  v        public.news_promos;
  v_tax    jsonb;
  v_refund bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'file_news_tax_return');
  if v_replay is not null then
    return v_replay;
  end if;
  v := public.news_promo_active(v_now);
  if v.id is null or v.kind <> 'tax_return' then
    perform public.api_error('news_promo_inactive');
  end if;
  perform 1 from public.profiles p where p.id = v_player for update;
  if exists (select 1 from public.news_promo_claims x where x.promo_id = v.id and x.player_id = v_player) then
    perform public.api_error('news_promo_claimed');
  end if;
  v_tax := public.news_promo_tax(v_player, v_now);
  if not (v_tax ->> 'owner')::boolean then
    perform public.api_error('news_promo_no_company');
  end if;
  v_refund := (v_tax ->> 'refund_cents')::bigint;
  if v_refund <= 0 then
    perform public.api_error('tax_nothing_due');
  end if;
  -- the state pays from the treasury; an empty treasury pays nothing
  if coalesce((select x.balance_cents from public.ledger_accounts x where x.id = public.ledger_system_account('treasury') for update), 0)
     < v_refund then
    perform public.api_error('tax_nothing_due');
  end if;
  perform public.lock_player_accounts(v_player);
  perform public.ledger_transfer(public.ledger_system_account('treasury'), public.ledger_player_account(v_player, 'player_cash'),
                                 v_refund, 'tax_refund', 'Steuererklärung (News-Aktion)', 'news_promo', null,
                                 'news_promo:tax:' || v.id::text || ':' || v_player::text, v_player,
                                 jsonb_build_object('promo_id', v.id, 'revenue_cents', v_tax -> 'revenue_cents'));
  insert into public.news_promo_claims (promo_id, player_id, amount_cents, revenue_cents)
  values (v.id, v_player, v_refund, (v_tax ->> 'revenue_cents')::bigint);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'promo_id', v.id, 'refund_cents', v_refund, 'revenue_cents', (v_tax ->> 'revenue_cents')::bigint));
end;
$$;
comment on function public.file_news_tax_return(uuid) is
  'RPC: files the tax return of a running tax_return News-Aktion (ADR-193), once per player -> '
  '{promo_id, refund_cents, revenue_cents}; idempotent. Errors news_promo_inactive, news_promo_claimed, '
  'news_promo_no_company, tax_nothing_due.';
revoke all on function public.file_news_tax_return(uuid) from public, anon;
grant execute on function public.file_news_tax_return(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Pack sale: the two pack purchases with the promotion price (full latest definitions)
-- ---------------------------------------------------------------------------
create or replace function public.buy_nexamon_pack(p_request_id uuid, p_set text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  cfg      jsonb := public.nexamon_cfg();
  v_player uuid;
  v_replay jsonb;
  v_now    timestamptz := public.game_now();
  v_price  bigint;
  v_cash   bigint;
  v_pack   uuid := gen_random_uuid();
  v_cards  jsonb;
  r        record;
begin
  v_player := public.require_player();
  perform public.nexamon_require_unlock(v_player);
  if p_request_id is null or p_set is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_nexamon_pack');
  if v_replay is not null then
    return v_replay;
  end if;
  perform public.nexamon_sync(v_now);
  v_price := (cfg #>> array['sets', p_set, 'packPriceCents'])::bigint;
  if v_price is null or v_price < 0 or not exists (select 1 from public.nexamon_cards k where k.set_key = p_set and k.in_catalogue) then
    perform public.api_error('nexamon_unknown');
  end if;
  if not public.nexamon_set_released(p_set, public.game_now()) then
    perform public.api_error('nexamon_set_not_released');
  end if;
  -- ADR-193: a running pack sale of this set
  v_price := public.news_promo_pack_price(p_set, v_price, v_now);
  if not public.rate_limit_hit(v_player, 'nexamon_pack', coalesce((cfg #>> '{packs,perMinute}')::integer, 20), 60) then
    perform public.api_error('rate_limited');
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_price then
    perform public.api_error('insufficient_funds');
  end if;
  if v_price > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_price, 'nexamon_pack', 'Booster gekauft: ' || coalesce(cfg #>> array['sets', p_set, 'name'], p_set),
                                   'nexamon_pack', v_pack, 'nexamon:pack:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('set', p_set, 'price_cents', v_price));
  end if;
  v_cards := public.nexamon_open_pack(p_set, v_player, null, v_pack, v_now);
  insert into public.nexamon_packs (id, player_id, set_key, price_cents, cards, opened_at)
  values (v_pack, v_player, p_set, v_price, v_cards, v_now);
  update public.nexamon_set_state set player_packs_opened = player_packs_opened + 1 where set_key = p_set;
  perform public.mission_event(v_player, 'nexamon_pack', 1, null);
  for r in select x ->> 'rarity' as rarity from jsonb_array_elements(v_cards) x loop
    if public.nexamon_rarity_rank(r.rarity) >= 1 then
      perform public.mission_event(v_player, 'nexamon_rare', 1, null);
    end if;
    if public.nexamon_rarity_rank(r.rarity) >= 2 then
      perform public.mission_event(v_player, 'nexamon_ultra', 1, null);
    end if;
  end loop;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'pack_id', v_pack, 'set', p_set, 'price_cents', v_price, 'cards', v_cards,
    'packs_opened', (select count(*) from public.nexamon_packs p where p.player_id = v_player and p.set_key = p_set)));
end;
$function$;

create or replace function public.buy_nexamon_sealed_pack(p_request_id uuid, p_set text, p_count integer default 1)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  cfg      jsonb := public.nexamon_cfg();
  v_player uuid;
  v_replay jsonb;
  v_now    timestamptz := public.game_now();
  v_price  bigint;
  v_total  bigint;
  v_cash   bigint;
  v_max    integer := coalesce((public.nexamon_cfg() #>> '{packs,perMinute}')::integer, 20);
begin
  v_player := public.require_player();
  perform public.nexamon_require_unlock(v_player);
  if p_request_id is null or p_set is null or p_count is null or p_count < 1 or p_count > v_max then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_nexamon_sealed_pack');
  if v_replay is not null then
    return v_replay;
  end if;
  v_price := (cfg #>> array['sets', p_set, 'packPriceCents'])::bigint;
  if v_price is null or v_price < 0 or not exists (select 1 from public.nexamon_cards k where k.set_key = p_set and k.in_catalogue) then
    perform public.api_error('nexamon_unknown');
  end if;
  if not public.nexamon_set_released(p_set, public.game_now()) then
    perform public.api_error('nexamon_set_not_released');
  end if;
  -- ADR-193: a running pack sale of this set
  v_price := public.news_promo_pack_price(p_set, v_price, v_now);
  if not public.rate_limit_hit(v_player, 'nexamon_pack', v_max, 60) then
    perform public.api_error('rate_limited');
  end if;
  v_total := v_price * p_count;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_total then
    perform public.api_error('insufficient_funds');
  end if;
  if v_total > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_total, 'nexamon_pack',
                                   'Booster gekauft (ungeöffnet): ' || p_count || ' × ' || coalesce(cfg #>> array['sets', p_set, 'name'], p_set),
                                   'nexamon_pack', null, 'nexamon:sealed:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('set', p_set, 'price_cents', v_price, 'count', p_count, 'sealed', true));
  end if;
  perform public.nexamon_grant_sealed_packs(v_player, p_set, p_count, 'bought', null, v_price);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'set', p_set, 'count', p_count, 'price_cents', v_total, 'packs', public.nexamon_sealed_json(v_player)));
end;
$function$;

-- ---------------------------------------------------------------------------
-- Free NFT: create_artwork (full latest definition) skips the fee once per player and promotion
-- ---------------------------------------------------------------------------
create or replace function public.create_artwork(p_request_id uuid, p_title text, p_pixels jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_player  uuid;
  v_replay  jsonb;
  v_title   text := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g'));
  v_reason  text;
  v_painted integer;
  v_cost    bigint;
  v_cash    bigint;
  v_xp      integer;
  v_id      uuid := gen_random_uuid();
  v_promo   public.news_promos;
  v_free    boolean := false;
  v_mint    bigint;
begin
  v_player := public.require_player();
  perform public.artworks_require_unlock(v_player);
  if p_request_id is null or not public.artwork_valid(p_pixels) then
    perform public.api_error('invalid_argument');
  end if;
  v_reason := public.artwork_title_violation(v_title);
  if v_reason is not null then
    perform public.api_error(v_reason);
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'create_artwork');
  if v_replay is not null then
    return v_replay;
  end if;
  -- unique titles (ADR-100): lookalikes count as the same title; the lock serialises two painters of one title
  perform pg_advisory_xact_lock(hashtextextended('artwork_title:' || public.name_key(v_title), 0));
  if public.artwork_title_taken(v_title) then
    perform public.api_error('name_taken');
  end if;
  if public.logo_has_forbidden_symbol(p_pixels -> 'grid') then
    perform public.api_error('logo_forbidden');
  end if;
  -- one painting at a time per player (the count decides the price)
  perform 1 from public.profiles p where p.id = v_player for update;
  v_painted := public.player_artworks_minted_today(v_player);
  -- artist upgrade (ADR-100): the price x (10 000 − artDiscountBps) / 10 000
  v_cost := public.player_artwork_create_cost_cents(v_player, v_painted);
  -- ADR-193: a running free-NFT promotion waives the fee once per player; the NFT keeps its normal mint value
  v_mint := v_cost;
  v_promo := public.news_promo_active(public.game_now());
  if v_promo.id is not null and v_promo.kind = 'free_nft'
     and not exists (select 1 from public.news_promo_claims x where x.promo_id = v_promo.id and x.player_id = v_player) then
    insert into public.news_promo_claims (promo_id, player_id, amount_cents, ref_id)
    values (v_promo.id, v_player, v_cost, v_id);
    v_free := true;
    v_cost := 0;
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('treasury'),
                                   v_cost, 'artwork_creation', 'NFT geprägt', 'artwork', v_id,
                                   'art:create:' || v_id::text, v_player, jsonb_build_object('painted_before', v_painted,
                                                                     'discount_bps', public.player_art_discount_bps(v_player)));
  end if;
  insert into public.artworks (id, title, origin, rarity, creator_id, owner_id, pixels, mint_cents)
  values (v_id, v_title, 'player', null, v_player, v_player,
          jsonb_build_object('palette', p_pixels -> 'palette', 'grid', p_pixels -> 'grid'), v_mint);
  perform public.mission_event(v_player, 'art_painted', 1, null);
  -- minting is worth XP (ADR-135)
  v_xp := public.grant_xp(v_player, 'nft_mint', coalesce((public.nfts_cfg() ->> 'mintXp')::integer, 0),
                          'nft_mint:' || v_id::text, 'artwork', v_id);
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'artwork', public.artwork_json(v_id, v_player),
    'cost_cents', v_cost,
    'free', v_free,
    'xp', coalesce(v_xp, 0),
    'next_cost_cents', public.player_artwork_create_cost_cents(v_player, v_painted + 1)));
end;
$function$;

commit;
